/**
 * scripts/generate-multisig-owners.ts
 *
 * Generates 3 fresh EOA private keys + addresses for the MultisigTreasury
 * 2-of-3 owners. Saves to .env.multisig-keys (gitignored).
 *
 * Usage:
 *   node --env-file=.env.local --import tsx scripts/generate-multisig-owners.ts
 *
 * The generated file is .env.multisig-keys — DO NOT COMMIT. Add to .gitignore.
 * For testnet only — rotate to hardware wallets before mainnet.
 */
import { generatePrivateKey, privateKeyToAccount } from "viem/accounts";
import { writeFileSync, readFileSync, existsSync } from "fs";
import { resolve } from "path";

const ROOT = resolve(__dirname, "..");
const OUT_FILE = resolve(ROOT, ".env.multisig-keys");

function main() {
  // If file already exists, preserve + append a comment.
  let header = "# Multisig Treasury Owners (TESTNET ONLY — generate fresh for mainnet)\n";
  header += "# Generated by scripts/generate-multisig-owners.ts on " + new Date().toISOString() + "\n";
  header += "# 2-of-3 required confirmations on MultisigTreasury.\n";
  header += "# DO NOT COMMIT — already in .gitignore (verify!).\n\n";

  const lines: string[] = [];
  const addresses: string[] = [];
  for (let i = 1; i <= 3; i++) {
    const pk = generatePrivateKey();
    const account = privateKeyToAccount(pk);
    lines.push(`MULTISIG_OWNER_${i}_PRIVATE_KEY=${pk}`);
    lines.push(`MULTISIG_OWNER_${i}_ADDRESS=${account.address}`);
    addresses.push(account.address);
    console.log(`Owner ${i}: ${account.address}`);
  }

  const content = header + lines.join("\n") + "\n";
  writeFileSync(OUT_FILE, content, { mode: 0o600 });
  console.log(`\n✓ Wrote ${OUT_FILE}`);
  console.log(`  Add MULTISIG_OWNER_1/2/3_ADDRESS to .env.local if you want them there.`);
  console.log(`  Private keys are in .env.multisig-keys (gitignored).`);

  // Print addresses for easy copy-paste to deploy.ts.
  console.log(`\nAddresses for deploy.ts:`);
  console.log(`  [${addresses.map(a => `"${a}"`).join(", ")}]`);
}

main();
